CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', avatar_url text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', preferences jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE TYPE public.app_role AS ENUM ('seller','agency','admin');
CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE TABLE public.agencies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, name text NOT NULL, logo_url text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.agencies TO authenticated; GRANT ALL ON public.agencies TO service_role;
ALTER TABLE public.agencies ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.agency_members (agency_id uuid REFERENCES public.agencies(id) ON DELETE CASCADE, user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, member_role text NOT NULL DEFAULT 'agent' CHECK(member_role IN ('owner','agent')), PRIMARY KEY(agency_id,user_id));
GRANT SELECT ON public.agency_members TO authenticated; GRANT ALL ON public.agency_members TO service_role;
ALTER TABLE public.agency_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_membership ON public.agency_members FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE POLICY member_agency_read ON public.agencies FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.agency_members m WHERE m.agency_id=id AND m.user_id=auth.uid()));
CREATE POLICY owner_agency_update ON public.agencies FOR UPDATE TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE TABLE public.favorites (user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, listing_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,listing_id));
GRANT SELECT, INSERT, DELETE ON public.favorites TO authenticated; GRANT ALL ON public.favorites TO service_role;
ALTER TABLE public.favorites ENABLE ROW LEVEL SECURITY;
CREATE POLICY favorite_read ON public.favorites FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY favorite_insert ON public.favorites FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY favorite_delete ON public.favorites FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.initialize_account() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id,full_name,avatar_url) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'full_name',NEW.raw_user_meta_data->>'name',''),coalesce(NEW.raw_user_meta_data->>'avatar_url','')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'seller'); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.initialize_account() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER initialize_account AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.initialize_account();
CREATE FUNCTION public.create_my_agency(agency_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE aid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF length(trim(agency_name)) < 2 OR length(trim(agency_name)) > 100 THEN RAISE EXCEPTION 'Invalid agency name'; END IF; SELECT agency_id INTO aid FROM public.agency_members WHERE user_id=auth.uid() LIMIT 1; IF aid IS NOT NULL THEN RETURN aid; END IF; INSERT INTO public.agencies(owner_id,name) VALUES(auth.uid(),trim(agency_name)) RETURNING id INTO aid; INSERT INTO public.agency_members(agency_id,user_id,member_role) VALUES(aid,auth.uid(),'owner'); INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),'agency') ON CONFLICT DO NOTHING; RETURN aid; END $$;
REVOKE ALL ON FUNCTION public.create_my_agency(text) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.create_my_agency(text) TO authenticated;
CREATE FUNCTION public.add_agency_member(member_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE aid uuid; BEGIN SELECT id INTO aid FROM public.agencies WHERE owner_id=auth.uid() LIMIT 1; IF aid IS NULL THEN RAISE EXCEPTION 'Forbidden'; END IF; INSERT INTO public.agency_members(agency_id,user_id) VALUES(aid,member_id) ON CONFLICT DO NOTHING; INSERT INTO public.user_roles(user_id,role) VALUES(member_id,'agency') ON CONFLICT DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.add_agency_member(uuid) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.add_agency_member(uuid) TO authenticated;